import { readdirSync, readFileSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";

const webRoot = path.resolve(__dirname, "../../..");
const routes = JSON.parse(readFileSync(path.join(webRoot, "public/_routes.json"), "utf8")) as {
  include: string[];
  exclude: string[];
};
const functionEntries = readdirSync(path.join(webRoot, "functions"), { withFileTypes: true });

// Every Function run is billed against the shared Workers daily limit, so the routed paths
// are pinned here instead of being generated by Pages from functions/.
describe("public/_routes.json", () => {
  it("never routes the whole site (assets, sw.js) through the Function", () => {
    expect(routes.include).not.toContain("/*");
    expect(routes.include.every((route) => /^\/[a-z-]+\/\*$/.test(route))).toBe(true);
  });

  it("has no root-level function such as a catch-all _middleware.ts", () => {
    expect(functionEntries.filter((entry) => !entry.isDirectory()).map((entry) => entry.name)).toEqual([]);
  });

  it("routes exactly the directories under functions/", () => {
    const expected = functionEntries.map((entry) => `/${entry.name}/*`).sort();
    expect([...routes.include].sort()).toEqual(expected);
  });
});
